settings.custom_css:
.m-slider--home .m-slide__subtitle,
.m-slider--home .m-slide__title {
  font-weight: 500;
}
.m-slider--home .m-slide__subtitle,
body .m-richtext__description,
.m-image-box--home .m-icon-box__heading {
  font-family: 'M-Body-Font';
}
body .m-section__header {
  margin-bottom: 30px;
}
.m-collection-list--home .m-collection-card__image,
.m-custom--banner .m-image-card {
  border-radius: 10px;
}
.custom__html-block2 {
  padding: 70px 80px;
  background-image: url(https://cdn.shopify.com/s/files/1/0561/2742/2636/files/bg.jpg?v=1622194012);
  background-size: no-repeat;
  background-size: cover;
  background-position: center;
  border-radius: 8px;
}
.custom__html-block2 .block__content {
  text-align: center;
  display: inline-block;
}
.custom__html-block2 .block__content h2 {
  color: #fff;
  margin-bottom: 6px;
  margin-top: 0;
}
.custom__html-block2 .block__content p {
  color: rgba(255, 255, 255, 0.7);
}
.custom__html-block2 .block__social {
  margin-top: 50px;
  text-align: center;
}
.custom__html-block2 .block__social ul {
  margin: 0 -20px;
  padding-left: 0;
}
.custom__html-block2 .block__social ul li {
  display: inline-block;
  padding: 0 20px;
}
.custom__html-block2 .block__social ul li a {
  display: flex;
  align-items: center;
  color: #fff;
}
.custom__html-block2 .block__social ul li a img {
  height: 15px;
  margin-right: 10px;
  margin-top: 0;
  margin-bottom: 0;
}
.custom__html-block1 {
  padding: 0 70px;
  position: relative;
}
.custom__html-block1::after {
  position: absolute;
  content: "";
  top: 22px;
  left: 0;
  width: 100%;
  height: calc(100% - 56px);
  border-radius: 8px;
  background: #e3ebec;
}
.custom__html-block1 img {
  max-width: 300px;
  margin-right: 70px;
}
.custom__html-block1 .block__content {
  position: relative;
  z-index: 1;
}
.custom__html-block1 .block__content-text {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
}
.custom__html-block1 .block__content-text .block__heading h3 {
  font-size: 40px;
  line-height: 56px;
  margin-bottom: 4px;
}
.custom__html-block1 .block__content-text .block__heading p {
  color: #696969;
}

@media (min-width: 768px) {
  .m-slider--home .m-slide__subtitle {
    font-size: 24px;
  }
}
@media(max-width: 767px) {
  .sf-custom--3 .m-section-my {
    margin-bottom: 40px;
  }
  .custom__html-block1 {
    padding: 0 20px 20px;
  }
  .custom__html-block1 .block__content,
  .custom__html-block1 .block__content-text {
    flex-direction: column;
    text-align: center;
  }
  .custom__html-block1 img {
    margin-right: 0;
  }
  .custom__html-block1 .block__content-text .block__heading h3 {
    font-size: 24px;
    line-height: 30px;
    margin-top: 20px;
  }
  .custom__html-block1 .block__content-text .block__heading p {
    margin-bottom: 20px;
  }
  .custom__html-block1::after {
    height: 100%;
  }
  .custom__html-block2 {
    padding: 50px 20px;
    background-position: left;
  }
  .custom__html-block2 .block__content h3 {
    font-size: 24px;
    line-height: 30px;
  }
  .custom__html-block2 .block__social ul li {
    margin-bottom: 15px;
  }
}

